arguments.command:
set -e
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq nginx
mkdir -p /var/www/html /etc/nginx/conf.d
printf '%s\n' 'Welcome to the benchmark webserver' > /var/www/html/index.html
printf '%s\n' 'Page not found - Please check your URL' > /var/www/html/404.html
rm -f /etc/nginx/sites-enabled/default
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark_detailed;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF
python3 - <<'PY'
from pathlib import Path
p = Path('/etc/nginx/nginx.conf')
s = p.read_text()
log = '''\n    log_format benchmark_detailed '$time_local "$request_method" $status "$http_user_agent"';\n'''
# Insert definitions inside http{}, only if absent.
if 'log_format benchmark_detailed ' not in s:
    marker = 'http {\n'
    if marker not in s:
        raise SystemExit('http block not found')
    s = s.replace(marker, marker + log, 1)
if 'limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;' not in s:
    marker = 'http {\n'
    s = s.replace(marker, marker + '    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;\n', 1)
p.write_text(s)
PY
nginx -t
if command -v systemctl >/dev/null 2>&1; then systemctl enable nginx >/dev/null 2>&1 || true; systemctl restart nginx; else nginx -s reload 2>/dev/null || nginx; fi
sleep 1
printf '\n--- service/listener ---\n'
(ss -ltnp 2>/dev/null || netstat -ltnp 2>/dev/null) | grep ':8080' || true
printf '\n--- localhost test ---\n'
printf 'index: '; curl -fsS http://localhost:8080/
printf 'missing status: '; curl -sS -o /tmp/benchmark-404.out -w '%{http_code}\n' http://localhost:8080/not-found
printf 'missing body: '; cat /tmp/benchmark-404.out
printf '\naccess log: /var/log/nginx/benchmark-access.log\n'
tail -n 3 /var/log/nginx/benchmark-access.log 2>/dev/null || true

